import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Cx5sLWzU.js";const p=JSON.parse('{"title":"可视化配置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/config-builder.md","filePath":"guide/config-builder.md","lastUpdated":1792740363000}'),i={name:"guide/config-builder.md"};function d(l,e,s,n,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="可视化配置" tabindex="-1">可视化配置 <a class="header-anchor" href="#可视化配置" aria-label="Permalink to &quot;可视化配置&quot;">​</a></h1><p>不想手写 Lua？可以用交互式 <strong>WezTerm 可视化配置生成器</strong>：勾选人群预设与选项，实时预览 <code>.wezterm.lua</code>，一键复制后放到用户目录即可热重载。</p><h2 id="打开生成器" tabindex="-1">打开生成器 <a class="header-anchor" href="#打开生成器" aria-label="Permalink to &quot;打开生成器&quot;">​</a></h2><ul><li>可视化 Page：<a href="https://cursor.com/canvas/store-5a558b8d-8fd6-47e7-ba7c-ef09c785d456/f81fac06-99e6-4119-8421-c1f9b07c9eed" target="_blank" rel="noreferrer">WezTerm 可视化配置生成器</a></li><li>本仓库也可直接下载起步配置（请用下方<strong>外链</strong>，勿点站内相对路径）：见 <a href="#下载本仓库起步配置">下载本仓库起步配置</a>（Windows + 开发者 / AI 偏向精简版）</li></ul><div class="tip custom-block"><p class="custom-block-title">局限说明</p><p>生成器页面状态<strong>不会</strong>在刷新后保留；若浏览器沙箱限制剪贴板，请手动选中预览区文本复制。</p></div><h2 id="开启后长什么样" tabindex="-1">开启后长什么样？ <a class="header-anchor" href="#开启后长什么样" aria-label="Permalink to &quot;开启后长什么样？&quot;">​</a></h2><p>生成器里的开关对应手册中的真实截图。勾选前可先看：</p><ul><li><a href="./preview-gallery">效果图廊</a>（滚动条、分屏、命令面板、状态栏、Leader…）</li><li>命令面板语言：<a href="./faq#内置命令-命令面板能不能汉化">FAQ · 内置命令能不能汉化</a>（<strong>官方无 UI 汉化</strong>；可用 <code>augment-command-palette</code> / <code>InputSelector</code> 追加中文）</li></ul><div class="tip custom-block"><p class="custom-block-title">Windows Acrylic</p><p><code>win32_system_backdrop = &#39;Acrylic&#39;</code> 为 <strong>Windows 专属</strong>。Linux 手册截图只能示意半透明（<code>window_background_opacity</code>），不能代替亚克力模糊效果。</p></div><h2 id="三步上手" tabindex="-1">三步上手 <a class="header-anchor" href="#三步上手" aria-label="Permalink to &quot;三步上手&quot;">​</a></h2><ol><li>在生成器里选 <strong>人群预设</strong> 与 <strong>操作系统</strong>，按需微调开关与字体 / Shell 路径。</li><li>点「复制配置」，或从下方 <a href="#下载本仓库起步配置">下载本仓库起步配置</a> 用外链保存。</li><li>保存为： <ul><li>Windows：<code>%USERPROFILE%\\.wezterm.lua</code>（例如 <code>C:\\Users\\admin\\.wezterm.lua</code>）</li><li>Linux / macOS：<code>~/.wezterm.lua</code></li></ul></li><li>WezTerm 会自动热重载；也可按 <code>Ctrl+Shift+R</code> 强制重载。</li></ol><h2 id="人群预设一览" tabindex="-1">人群预设一览 <a class="header-anchor" href="#人群预设一览" aria-label="Permalink to &quot;人群预设一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>预设</th><th>适合谁</th><th>大致开启内容</th></tr></thead><tbody><tr><td><strong>轻度日常</strong> <code>light</code></td><td>只想换字体 / Shell / 滚动条</td><td>Shell、字体、滚动条、回滚 10000、默认快捷键注释、社区分屏 <code>Ctrl+Shift+\\|</code>/<code>-</code>；无 Leader、无花哨状态栏、无 AI 键</td></tr><tr><td><strong>开发者</strong> <code>dev</code></td><td>日常编码</td><td>light + 彩色标签、分屏键（<code>Ctrl+Shift+|</code> / <code>Ctrl+Shift+-</code>，Lua <code>_</code>）、Alt 切窗格、搜索相关说明、<code>Shift</code> 穿透鼠标、<code>Ctrl+Shift+Home/End</code></td></tr><tr><td><strong>AI 编程重度</strong> <code>ai</code></td><td>Claude Code / Codex / Gemini CLI 等</td><td>dev + 回滚 50000、滚动条、AI 注释、可选工作区键 / 旁开分屏、可选响铃 Toast</td></tr><tr><td><strong>运维多会话</strong> <code>ops</code></td><td>多工作区 / 类 tmux</td><td>ai + <code>update-status</code> 状态栏 + Leader=<code>Ctrl+A</code> 与工作区切换</td></tr><tr><td><strong>自定义</strong> <code>custom</code></td><td>自己勾选</td><td>切换预设后再改开关；选 custom 会保留当前勾选</td></tr></tbody></table><p>操作系统选项会影响 <code>default_prog</code> 默认值与字体回退链：</p><table tabindex="0"><thead><tr><th>OS</th><th>默认 Shell</th><th>字体回退（示意）</th></tr></thead><tbody><tr><td>Windows（默认）</td><td><code>C:/Program Files/PowerShell/7/pwsh.exe</code> + <code>-NoLogo</code></td><td>Cascadia Code → Consolas → Microsoft YaHei UI</td></tr><tr><td>Linux</td><td><code>/bin/bash</code></td><td>JetBrains Mono → DejaVu Sans Mono → Noto Sans CJK SC</td></tr><tr><td>macOS</td><td><code>/bin/zsh</code></td><td>SF Mono → Menlo → PingFang SC</td></tr></tbody></table><h2 id="选项分类-与生成器一致" tabindex="-1">选项分类（与生成器一致） <a class="header-anchor" href="#选项分类-与生成器一致" aria-label="Permalink to &quot;选项分类（与生成器一致）&quot;">​</a></h2><ol><li><strong>启动与 Shell</strong> — <code>default_prog</code>、可选初始行列</li><li><strong>字体与外观</strong> — <code>font_with_fallback</code>、字号、配色、透明度、Windows Acrylic</li><li><strong>滚动与鼠标</strong> — 滚动条、<code>scrollback_lines</code>、<code>bypass_mouse_reporting_modifiers</code>、打字隐藏指针</li><li><strong>标签栏</strong> — <code>use_fancy_tab_bar</code>、<code>tab_max_width</code>、彩色 <code>format-tab-title</code>、标签栏背景</li><li><strong>分屏与窗格</strong> — 社区常用 <code>Ctrl+Shift+\\|</code> / <code>-</code>（叠加默认）、Alt 方向键、关闭窗格</li><li><strong>滚动快捷键</strong> — 补充 <code>Ctrl+Shift+Home/End</code>（Page 滚动仍是默认）</li><li><strong>常用工具键</strong> — 仅注释说明默认 <code>T/W/F/P/R/C/V</code> 等，避免重复绑定</li><li><strong>Leader 键（重度）</strong> — <code>Ctrl+A</code> + 类 tmux 绑定（默认关，ops 开）</li><li><strong>状态栏</strong> — <code>update-status</code>（cwd / 工作区 / 时间；默认关，ops 开）</li><li><strong>AI 编程辅助</strong> — 备用屏幕说明、旁开分屏、工作区键、Toast</li></ol><p>生成结果遵循：</p><ul><li><code>local wezterm = require &#39;wezterm&#39;</code> + <code>config_builder()</code> + <code>return config</code></li><li><code>config.keys = config.keys or {}</code> 再 <code>table.insert</code></li><li>关闭项以 <code>-- 【默认关闭】…</code> 整段注释保留，便于手动打开</li><li>启用项带 <code>-- 【已启用】…</code> 中文说明</li></ul><h2 id="下载本仓库起步配置" tabindex="-1">下载本仓库起步配置 <a class="header-anchor" href="#下载本仓库起步配置" aria-label="Permalink to &quot;下载本仓库起步配置&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">为什么不用站内相对链接？</p><p>站内相对链接（如 <code>/wezterm.lua</code>）会被 <strong>VitePress SPA 客户端路由</strong>拦成软 404（页面显示 PAGE NOT FOUND），即使静态文件其实存在。请用下方<strong>绝对外链</strong>下载。</p></div><p>推荐按顺序尝试（国内网络优先 raw / jsDelivr）：</p><ol><li><strong>Primary（raw）</strong>：<a href="https://raw.githubusercontent.com/gradient30/wezterm-handbook-zh/gh-pages/wezterm.lua" target="_blank" rel="noreferrer">wezterm.lua</a></li><li><strong>Mirror（jsDelivr）</strong>：<a href="https://cdn.jsdelivr.net/gh/gradient30/wezterm-handbook-zh@gh-pages/wezterm.lua" target="_blank" rel="noreferrer">wezterm.lua</a></li><li><strong>备用路径（github.io/downloads）</strong>：<a href="https://gradient30.github.io/wezterm-handbook-zh/downloads/wezterm-starter.lua" target="_blank" rel="noreferrer">wezterm-starter.lua</a></li><li><strong>github.io 根路径（第三选项）</strong>：<a href="https://gradient30.github.io/wezterm-handbook-zh/wezterm.lua" target="_blank" rel="noreferrer">wezterm.lua</a> — 请<strong>新标签打开</strong>或<strong>右键另存为</strong>；若看到站点「PAGE NOT FOUND」软 404，改用上面的 raw / jsDelivr。</li></ol><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># PowerShell：用 raw.githubusercontent.com（下载更可靠）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-WebRequest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Uri </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://raw.githubusercontent.com/gradient30/wezterm-handbook-zh/gh-pages/wezterm.lua&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutFile </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">USERPROFILE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\.wezterm.lua&quot;</span></span></code></pre></div><p>该文件默认已启用开发者 + AI 常用项；Leader / 状态栏 / Acrylic / Toast 等重度项保持注释，可按需取消注释。</p><h2 id="相关章节" tabindex="-1">相关章节 <a class="header-anchor" href="#相关章节" aria-label="Permalink to &quot;相关章节&quot;">​</a></h2><ul><li><a href="/wezterm-handbook-zh/guide/config">配置文件</a> — 查找顺序与 <code>config_builder</code></li><li><a href="/wezterm-handbook-zh/guide/appearance">外观与标签栏</a></li><li><a href="/wezterm-handbook-zh/guide/keys-scroll">快捷键与滚动</a></li><li><a href="/wezterm-handbook-zh/guide/panes-tabs">分屏与标签</a></li><li><a href="/wezterm-handbook-zh/guide/recipes">玩法与配方</a></li><li><a href="/wezterm-handbook-zh/guide/ai-coding">AI 编程使用方案</a></li><li><a href="/wezterm-handbook-zh/guide/faq">常见问题 FAQ</a></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>生成器与起步配置为社区工具，行为以 <a href="https://wezterm.org" target="_blank" rel="noreferrer">wezterm.org</a> 与你本机 WezTerm 版本为准（建议 ≥ 20240203）。</p></div>`,28)])])}const u=t(i,[["render",d]]);export{p as __pageData,u as default};
